const leads = $input.all().map(i => i.json);
const flatLeads = Array.isArray(leads[0]) ? leads[0] : leads;

// 사업부별 집계
const units = { pension: 'A-달팽이', cnc: 'B-스토리팜', automation: 'C-AI자동화', webdev: 'D-웹개발' };
const byUnit = {};
const byStage = { cold: 0, warm: 0, hot: 0, customer: 0, fan: 0 };
const bySource = {};

flatLeads.forEach(l => {
  byUnit[l.business_unit] = (byUnit[l.business_unit] || 0) + 1;
  byStage[l.stage] = (byStage[l.stage] || 0) + 1;
  bySource[l.source] = (bySource[l.source] || 0) + 1;
});

const total = flatLeads.length;
const hotCount = flatLeads.filter(l => l.score >= 50).length;

let report = `📊 **일일 가망고객 수집 리포트**\n`;
report += `━━━━━━━━━━━━━━━━━━\n`;
report += `📅 ${new Date().toLocaleDateString('ko-KR', {timeZone:'Asia/Seoul'})}\n\n`;
report += `📦 **총 수집: ${total}건**\n`;
report += `🔥 Hot 리드: ${hotCount}건\n\n`;

report += `🏢 **사업부별**\n`;
Object.entries(byUnit).forEach(([k, v]) => {
  report += `  ${units[k] || k}: ${v}건\n`;
});

report += `\n📊 **등급별**\n`;
report += `  Cold: ${byStage.cold} | Warm: ${byStage.warm} | Hot: ${byStage.hot}\n`;
report += `  Customer: ${byStage.customer} | Fan: ${byStage.fan}\n`;

report += `\n📡 **출처별**\n`;
Object.entries(bySource).forEach(([k, v]) => {
  report += `  ${k}: ${v}건\n`;
});

return [{ json: { report, total, hotCount } }];
